import{_ as t,o as i,c as n,a2 as a}from"./chunks/framework.Cv-B11KK.js";const h=JSON.parse('{"title":"Writing LaTeX in BBEdit","description":"","frontmatter":{},"headers":[],"relativePath":"bbedit-editing.md","filePath":"bbedit-editing.md","lastUpdated":1790161609000}'),o={name:"bbedit-editing.md"};function s(r,e,l,c,d,p){return i(),n("div",null,[...e[0]||(e[0]=[a(`<h1 id="writing-latex-in-bbedit" tabindex="-1">Writing LaTeX in BBEdit <a class="header-anchor" href="#writing-latex-in-bbedit" aria-label="Permalink to &quot;Writing LaTeX in BBEdit&quot;">​</a></h1><h2 id="compile-and-view" tabindex="-1">Compile and view <a class="header-anchor" href="#compile-and-view" aria-label="Permalink to &quot;Compile and view&quot;">​</a></h2><ul><li>⌘K: compile using document settings and sync Skim in the background.</li><li>⇧⌘K: choose an engine or named project profile for this build.</li><li>LaTeX — Cancel Build stops the project&#39;s active compiler and its children.</li><li>LaTeX — Preview Selection renders selected math in a compact BBEdit window using the main-file preamble. Select a complete equation or raw math first; see <a href="./selection-preview">preview details</a>.</li><li>LaTeX — Open Preview Log opens the current preview request&#39;s log. Status in the preview window distinguishes current output from rendering, stale, or failed output.</li><li>LaTeX — Clean preserves the PDF; Clean All Build Output removes it after confirmation.</li><li>Use LaTeX — Forward Search to locate the source position in Skim. Existing personal key assignments are preserved.</li><li>Cmd-click in Skim returns to BBEdit when Skim inverse search is configured.</li><li>Errors appear automatically in LaTeX Results. Warnings and bad boxes are available through LaTeX — Show Build Results without rebuilding.</li><li>LaTeX — Open Build Log opens the current root&#39;s compiler output, or its project&#39;s LaTeX log. If no project log exists, it shows the latest global compiler output (which may belong to another document).</li><li>Successful builds do not open a results window or play a sound. If SyncTeX is unavailable, the PDF still opens in Skim without taking focus.</li></ul><p>Compilation saves modified <code>.tex</code>, <code>.bib</code>, <code>.sty</code>, and <code>.cls</code> documents open under the project directory, plus the explicit root. Configure roots, output directories, and profiles in <a href="./project-builds">a project <code>.bbtex</code> file</a>.</p><h2 id="native-completion-and-navigation" tabindex="-1">Native completion and navigation <a class="header-anchor" href="#native-completion-and-navigation" aria-label="Permalink to &quot;Native completion and navigation&quot;">​</a></h2><p>TexLab supplies the editor&#39;s LaTeX intelligence; bbtex runs explicit builds. The installed TexLab was verified with label completion, citation completion, and reference-to-label definition requests using a disposable test project. BBEdit was also verified to start TexLab when opening a saved TeX file. This does not test every completion-popup interaction in the editor.</p><p>In a TeX document:</p><ul><li>Choose <strong>Edit → Complete</strong> inside \\ref{...} and \\cite{...}. This installation uses <strong>⇧⌘C</strong>, reassigned from Copy &amp; Append (which remains available in the Edit menu). BBEdit&#39;s factory shortcut is F5, possibly Fn-F5. For example, type <code>\\ref{eq:</code> and invoke Complete. The current shortcut is shown in the Edit menu and can be changed in Settings → Menus &amp; Shortcuts.</li><li>Command-double-click a reference, or use Go &gt; Go to Definition.</li><li>Use Search &gt; Find References to Selected Symbol for references.</li><li>Use Search &gt; Find Symbol in Workspace to navigate project symbols.</li><li>Use <strong>Scripts → LaTeX — Project Outline</strong> for a searchable saved-file outline of sections, equations, figures, tables, and labels across included files. Duplicate labels retain their locations; stale targets require a fresh search. See <a href="./project-navigation">project navigation</a> for scope and keyboard usage.</li><li>Use View &gt; Text Display &gt; Show Issues for source diagnostics.</li><li><strong>Scripts → LaTeX — Insert Citation / Insert Reference</strong> provide explicit metadata/context search and safe key insertion alongside native completion. <a href="./citation-reference-pickers">Picker usage and supported commands</a>.</li></ul><p>If completion is missing, inspect Settings &gt; Languages &gt; TeX &gt; Server. BBEdit&#39;s TeX module is preconfigured for texlab; a direct executable symlink in Language Servers avoids shell PATH differences. Open the actual project folder so the server can discover the bibliography and included files.</p><p>Do not enable a second automatic compilation workflow while using bbtex&#39;s explicit builds. Server completion/navigation do not require build-on-save.</p><p>Reference: <a href="https://hosting.barebones.com/support/bbedit/lsp-notes.html" target="_blank" rel="noreferrer">https://hosting.barebones.com/support/bbedit/lsp-notes.html</a></p><h2 id="imported-editing-tools" tabindex="-1">Imported editing tools <a class="header-anchor" href="#imported-editing-tools" aria-label="Permalink to &quot;Imported editing tools&quot;">​</a></h2><p>Scripts &gt; LaTeX Editing contains:</p><ul><li>Change Environment</li><li>Toggle Starred Environment</li><li>Wrap in Environment</li><li>Declare Math Operator</li><li>Package Documentation</li></ul><p>The former LaTeX clippings and stationery remain available. Scripted clippings for inserting and closing environments keep their shared environment library.</p><p>Place an empty cursor inside an environment (including either tag) to change its name or toggle its star. The innermost matched pair changes in one undoable edit; body text, indentation, and surrounding tags stay intact. The cursor follows the same position through the name changes, including Unicode before the cursor. Cancel leaves text and selection unchanged. Edits made while the rename dialog is open cause an explanatory refusal rather than applying an obsolete edit.</p><p>Matching uses the current unsaved buffer and skips comments, common verbatim environments, inline literal commands, and common macro/environment definitions. Nested identical names are supported. Malformed or crossed tags, dynamic names, selected text, and a cursor inside a comment, literal region, or definition are rejected. Names may contain letters, digits, <code>*</code>, <code>@</code>, and hyphens. Buffers are limited to 4 MiB; TeX macro expansion, custom literal syntax, and conditionals are outside this bounded scanner&#39;s scope.</p><p><strong>Wrap in Environment</strong> wraps selected complete lines, preserving their existing indentation and leaving the body selected. A selection may start after leading whitespace and end before the last line ending; the helper includes that line&#39;s indentation and trailing whitespace. It rejects partial prose lines and selections that cross environment boundaries. On a blank line, an empty selection inserts a paired environment and places the cursor in its body, one tab beyond the line&#39;s indentation. LF, CRLF, and CR line endings are retained by the planner (BBEdit normalizes its scripting text). Wrapping is one Undo and uses the same buffer and selection guards as renaming.</p><p>The Close Environment clipping uses the same scanner on text before the cursor and proposes the innermost still-open name; it does not inspect future closing tags. Failed matching aborts insertion and explains why. The custom begin/end clipping validates the environment name and the same whole-line/context boundaries, then rechecks the buffer/selection after its dialog. It retains its original indented body template; use Wrap in Environment to keep body indentation exactly. Cancellation and invalid input preserve selected text: scripted clippings abort instead of returning an empty replacement.</p><p>The existing fraction, matrix, minipage, and command clippings remain the route for argument placeholders. A local TexLab audit with snippet support enabled returned name completions for <code>\\frac</code> and <code>\\begin{equation}</code>, without argument placeholders. Two missing templates are now under <strong>links and images</strong>:</p><ul><li><strong>hyperlink (hyperref)</strong> wraps selected text in <code>\\href</code> and selects the URL placeholder; the document must load <code>hyperref</code>.</li><li><strong>image (graphicx)</strong> inserts <code>\\includegraphics</code> with width and filename placeholders, selecting width first; the document must load <code>graphicx</code>.</li></ul><p>These use BBEdit&#39;s native clipping placeholders and each insertion is one Undo. They do not add package declarations or alter TexLab&#39;s completion shortcut.</p><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><p>Each install moves the previous bbtex-support.bbpackage to ~/Library/Application Support/BBEdit/Backups/bbtex-TIMESTAMP-PID/. To go back, quit BBEdit, move the installed package out of Packages, put the backup in its place, then reopen BBEdit. (Backups from the retired Latex.bbpackage migration also contain that package and the previous shortcut file.)</p><h2 id="development-checks" tabindex="-1">Development checks <a class="header-anchor" href="#development-checks" aria-label="Permalink to &quot;Development checks&quot;">​</a></h2><p>Build the editing assets, then run the checks (Python checks run through uv; see <code>AGENTS.md</code>):</p><pre><code>scripts/build-support.sh
uv run test/integration/check_texlab.py
uv run test/integration/check_build_workflow.py
uv run test/integration/check_project_builds.py
uv run test/integration/check_project_saving.py
uv run test/integration/check_bbedit_texlab.py
uv run test/integration/check_results_browser.py
uv run test/integration/check_live_compile.py
scripts/install-support.sh
</code></pre><p>The last command previews the install. Add --apply --restart to install.</p><p>The native integration checks use disposable BBEdit documents/PDFs and require macOS application scripting access. The workflow check uses fake compilers and desktop commands to exercise failure paths without touching the editor.</p><p>After <code>dune build</code> and building support, verify environment edits with:</p><pre><code>osascript test/integration/check_editing.applescript &quot;$PWD/dist/bbtex-support.bbpackage/Contents/Scripts/LaTeX Editing/Toggle Starred Environment.scpt&quot; &quot;$PWD/dist/bbtex-support.bbpackage/Contents/Resources&quot;
</code></pre><p>This checks nested toggling, Unicode cursor positions, renaming, single Undo, and rejection of changed buffers/selections. <code>dune runtest</code> covers scanner edge cases. Release checks run the native test when <code>BBTEX_TEST_NATIVE=1</code> is set.</p><p><code>check_wrapping.applescript</code> takes the package Resources and <code>Clippings/Latex.tex</code> paths and verifies wrapping, empty insertion, selected bodies, native placeholders, and Undo. <code>uv run test/integration/check_structure_dialogs.py</code> tests the actual menu/clipping scripts with deterministic dialog answers, including cancellation and invalid input over selected text. Both are included in native release checks.</p>`,33)])])}const g=t(o,[["render",s]]);export{h as __pageData,g as default};
